// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/workbench/v1/auth/login", wrapper.Login)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/workbench/v1/auth/logout", wrapper.Logout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/workbench/v1/auth/me", wrapper.GetMe)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/workbench/v1/dev/config-schemas", wrapper.GetConfigSchemas)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/workbench/v1/dev/images", wrapper.PutImage)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/workbench/v1/dev/images/synthesize", wrapper.SynthesizeImage)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/workbench/v1/dev/images/{image_id}/degrade", wrapper.DegradeImage)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/workbench/v1/dev/views", wrapper.RenderView)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/workbench/v1/dev/artifacts/{artifact_id}", wrapper.GetArtifact)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/workbench/v1/dev/quality", wrapper.CheckQuality)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/workbench/v1/dev/barcode", wrapper.DecodeBarcode)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/workbench/v1/dev/invoice-qr", wrapper.LocateInvoiceQr)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/workbench/v1/dev/label", wrapper.PreprocessLabel)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/workbench/v1/dev/food", wrapper.PreprocessFood)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/workbench/v1/dev/sweeps", wrapper.RunSweep)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/workbench/v1/dev/batches", wrapper.RunBatch)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/workbench/v1/dev/e1/runs", wrapper.ListE1Runs)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/workbench/v1/dev/e1/runs", wrapper.StartE1Run)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/workbench/v1/dev/e1/runs/{run_id}", wrapper.GetE1Run)

	return m
}

